import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as t,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"Qwen glossary","description":"No how-to. This page only keeps the word “Qwen” consistent on this site.","frontmatter":{"title":"Qwen glossary","description":"No how-to. This page only keeps the word “Qwen” consistent on this site.","domain":"product","tags":["chat"],"role":"glossary"},"headers":[],"relativePath":"products/qwen/qwen-glossary.md","filePath":"products/qwen/qwen-glossary.md","lastUpdated":1787107158000}'),s={name:"products/qwen/qwen-glossary.md"};function i(r,a,l,p,h,d){return t(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="qwen-glossary" tabindex="-1">Qwen glossary <a class="header-anchor" href="#qwen-glossary" aria-label="Permalink to &quot;Qwen glossary&quot;">​</a></h1><p>No how-to. This page only keeps the word “Qwen” consistent on this site.</p><h2 id="concept-map" tabindex="-1">Concept map <a class="header-anchor" href="#concept-map" aria-label="Permalink to &quot;Concept map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alibaba / Tongyi</span></span>
<span class="line"><span>├── Qwen (assistant product, this directory)</span></span>
<span class="line"><span>│   ├── Web / App / desktop</span></span>
<span class="line"><span>│   ├── Office assistant / local PC / scheduled tasks (in-product)</span></span>
<span class="line"><span>│   └── Qwen IME (same-vendor app, no handbook)</span></span>
<span class="line"><span>├── Tongyi Lab (gateway: Qwen · Wan)</span></span>
<span class="line"><span>│   └── Wan (visual generation)</span></span>
<span class="line"><span>├── Tongyi Lingma / Qoder CN (coding assistant, #84)</span></span>
<span class="line"><span>├── Alibaba Cloud Bailian (model API platform, #85)</span></span>
<span class="line"><span>└── International Qwen</span></span>
<span class="line"><span>    ├── Qwen Studio (chat.qwen.ai)</span></span>
<span class="line"><span>    ├── Qwen Code (qwen.ai/qwencode)</span></span>
<span class="line"><span>    └── Research / open source (qwenlm.github.io / QwenLM)</span></span></code></pre></div><h2 id="qwen-千问" tabindex="-1">Qwen / 千问 <a class="header-anchor" href="#qwen-千问" aria-label="Permalink to &quot;Qwen / 千问&quot;">​</a></h2><p><strong>What it is:</strong> Alibaba’s consumer AI assistant. Official line: <strong>阿里官方AI助手</strong>. Door: <a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a>.</p><p><strong>Why it has a page:</strong> it is the personal chat-and-get-things-done product. It is not the lab gateway, the coding assistant, or the model API.</p><p><strong>What it is not:</strong> Tongyi Lab itself, Tongyi Lingma / Qoder CN, Bailian, or a CLI.</p><h2 id="tongyi-通义千问" tabindex="-1">Tongyi / 通义千问 <a class="header-anchor" href="#tongyi-通义千问" aria-label="Permalink to &quot;Tongyi / 通义千问&quot;">​</a></h2><p><strong>What it is:</strong> a brand word on the lab site and in older store copy. Tongyi Lab’s header says “千问 · 万相”. Yingyongbao still has a “通义介绍” block.</p><p><strong>Versus Qwen:</strong> the live consumer page’s product name is <strong>千问</strong>. Do not treat “Tongyi” as a second assistant, and do not promote stale store paragraphs into current features.</p><h2 id="tongyi-lab" tabindex="-1">Tongyi Lab <a class="header-anchor" href="#tongyi-lab" aria-label="Permalink to &quot;Tongyi Lab&quot;">​</a></h2><p><strong>What it is:</strong> a model and app gateway. <a href="https://tongyi.aliyun.com/" target="_blank" rel="noreferrer">tongyi.aliyun.com</a>. Footer “个人应用” points at Qwen.</p><p><strong>What it is not:</strong> a nickname for qianwen.com.</p><h2 id="wan" tabindex="-1">Wan <a class="header-anchor" href="#wan" aria-label="Permalink to &quot;Wan&quot;">​</a></h2><p><strong>What it is:</strong> Tongyi Lab’s visual-generation model family. Door: <a href="https://tongyi.aliyun.com/landing?family=wan" target="_blank" rel="noreferrer">landing?family=wan</a>. Qwen App video copy names <strong>Wan 2.7</strong>.</p><p><strong>What it is not:</strong> a tab name inside Qwen. This directory does not document a Wan console.</p><h2 id="tongyi-lingma-qoder-cn" tabindex="-1">Tongyi Lingma / Qoder CN <a class="header-anchor" href="#tongyi-lingma-qoder-cn" aria-label="Permalink to &quot;Tongyi Lingma / Qoder CN&quot;">​</a></h2><p><strong>What it is:</strong> Alibaba Cloud’s coding assistant. <a href="https://lingma.aliyun.com/" target="_blank" rel="noreferrer">lingma.aliyun.com</a> still exists; product pages and help also say <strong>Qoder CN</strong> (<a href="https://qoder.com.cn/" target="_blank" rel="noreferrer">qoder.com.cn</a>; help says the Lingma rename landed 2026-05-20). Site issue #84.</p><p><strong>Versus Qwen “code”:</strong> Qwen’s official wording is generating / checking mini programs, pages, mini games, and SQL in the thread. Qoder CN is the IDE / CLI product. This directory stops at this row.</p><h2 id="alibaba-cloud-bailian" tabindex="-1">Alibaba Cloud Bailian <a class="header-anchor" href="#alibaba-cloud-bailian" aria-label="Permalink to &quot;Alibaba Cloud Bailian&quot;">​</a></h2><p><strong>What it is:</strong> the model-service and app platform. <a href="https://www.aliyun.com/product/bailian" target="_blank" rel="noreferrer">aliyun.com/product/bailian</a>. Site issue #85.</p><p><strong>Versus Qwen “API 服务”:</strong> home has an <strong>API 服务</strong> button. Calling models and buying a Token Plan belong on Bailian. Do not teach <code>API Key</code> in the Qwen tutorial.</p><h2 id="qwen-studio" tabindex="-1">Qwen Studio <a class="header-anchor" href="#qwen-studio" aria-label="Permalink to &quot;Qwen Studio&quot;">​</a></h2><p><strong>What it is:</strong> the international assistant. <a href="https://chat.qwen.ai/" target="_blank" rel="noreferrer">chat.qwen.ai</a> and <a href="https://qwen.ai/" target="_blank" rel="noreferrer">qwen.ai</a> name the product <strong>Qwen Studio</strong>. qwen.ai copy: “an AI assistant for everyone, powered by the Qwen series models”.</p><p><strong>What it is not:</strong> the official English product name for 千问, and not an automatic mirror of qianwen.com. This directory does not write the install.</p><h2 id="qwen-code" tabindex="-1">Qwen Code <a class="header-anchor" href="#qwen-code" aria-label="Permalink to &quot;Qwen Code&quot;">​</a></h2><p><strong>What it is:</strong> the international terminal coding agent. <a href="https://qwen.ai/qwencode" target="_blank" rel="noreferrer">qwen.ai/qwencode</a> calls it an open-source AI agent for the terminal.</p><p><strong>What it is not:</strong> the <strong>代码</strong> chip on the Qwen home page.</p><h2 id="office-assistant-local-pc" tabindex="-1">Office assistant / local PC <a class="header-anchor" href="#office-assistant-local-pc" aria-label="Permalink to &quot;Office assistant / local PC&quot;">​</a></h2><p><strong>What they are:</strong> modes on qianwen.com. The banner says the office assistant unlocks local tasks, phone remote control, skills, and connectors.</p><p><strong>What they are not:</strong> QoderWork, and not the help-center product “千问办公 (QwenWork)”. That line sits next to #84. This directory does not write the install.</p><h2 id="qwen-ime" tabindex="-1">Qwen IME <a class="header-anchor" href="#qwen-ime" aria-label="Permalink to &quot;Qwen IME&quot;">​</a></h2><p><strong>What it is:</strong> the input-method app announced on the home banner. Yingyongbao package <code>com.qianwen.ime</code>.</p><p><strong>What it is not:</strong> a second chat assistant. No separate handbook.</p><h2 id="delivery-shapes-words-from-the-agreement" tabindex="-1">Delivery shapes (words from the agreement) <a class="header-anchor" href="#delivery-shapes-words-from-the-agreement" aria-label="Permalink to &quot;Delivery shapes (words from the agreement)&quot;">​</a></h2><p>The user agreement lists website <code>qianwen.com</code>, web, clients (iOS, Android, Windows, Mac, HarmonyOS), browser plugin, mini program, H5, and future carriers. The first group has public web / store doors. Plugin / mini program / HarmonyOS assistant install pages were not found on 2026-08-19 — keep the names, do not write install steps.</p><h2 id="do-not-write-these-as-product-names" tabindex="-1">Do not write these as product names <a class="header-anchor" href="#do-not-write-these-as-product-names" aria-label="Permalink to &quot;Do not write these as product names&quot;">​</a></h2><ul><li>“Qwen CLI”, “Qwen IDE plugin”, “Qwen international edition” — no official page uses them (the international site says Qwen Studio).</li><li>Calling a Bailian Token Plan or Coding Plan “Qwen membership pricing”.</li><li>Treating store-review quotas, takeout discounts, or default models as specs.</li><li>Listing Taobao / DingTalk / ECS as Qwen family products.</li></ul>`,39)])])}const b=e(s,[["render",i]]);export{u as __pageData,b as default};
